default_config         | {"workflow": {"steps": {"complete": {"action": "complete_workflow", "description": "Return the completed brief"}, "check_mode": {"action": "evaluate_condition", "config": {"default": "infer_via_llm", "conditions": {"auto": "infer_via_llm", "interactive": "collect_via_hitl"}, "condition_field": "input_data.hitl_mode"}, "next_step": "infer_via_llm", "description": "Determine if briefing should be interactive or auto-inferred"}, "infer_via_llm": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-haiku-4-5-20251001", "provider": "anthropic", "max_tokens": 4000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["input_data", "questionnaire"], "output_field": "brief_answers", "prompt_template": "You are completing a briefing questionnaire for a website project.\n\nProject Info:\n- Domain: {{.input_data.domain}}\n- Objective: {{.input_data.objective}}\n- Site Type: {{.input_data.site_type}}\n- Industry: {{.input_data.detected_industry}}\n\nQuestionnaire to complete:\n{{.questionnaire}}\n\nBased on the domain name, objective, and your knowledge of the industry, provide thoughtful answers to each question in the questionnaire.\n\nFor questions you cannot confidently answer from the available information, provide reasonable defaults appropriate for the industry.\n\nReturn your answers as a JSON object where keys match the field names in the questionnaire:\n{\n  \"field_name_1\": \"your answer\",\n  \"field_name_2\": \"your answer\",\n  ...\n}\n\nReturn ONLY valid JSON."}, "next_step": "complete"}, "collect_via_hitl": {"action": "request_human_input", "config": {"message": "Please complete the briefing questionnaire for this project", "request_type": "questionnaire", "timeout_seconds": 86400, "questionnaire_field": "questionnaire"}, "next_step": "complete", "description": "Collect answers via human-in-the-loop", "output_field": "brief_answers"}}, "start_step": "check_mode"}, "processing_mode": "task", "timeout_seconds": 120}
