"name": "site_type", "type": "select", "label": "Site Type", "options": ["landing", "content", "portfolio", "brochure"], "default_from": "classification.classify_site.result.site_type"}, {"name": "recommended_builder", "type": "dynamic_select", "label": "Builder", "default_from": "classification.classify_site.result.recommended_builder", "options_from": "available_builders.agents", "option_label_field": "display_name", "option_value_field": "type"}], "message": "Please confirm or adjust the site classification", "skip_if": "input_data.hitl_mode == auto", "request_type": "confirmation", "timeout_seconds": 86400}, "next_step": "fetch_questionnaire", "description": "Human confirms or adjusts the site type classification", "output_field": "confirmed_type"}, "hitl_review_brief": {"action": "request_human_input", "config": {"title": "Review Brief", "message": "Please review and adjust the briefing answers if needed", "skip_if": "input_data.hitl_mode == auto", "editable": true, "data_field": "brief_data", "request_type": "review", "timeout_seconds": 86400}, "next_step": "spawn_builder", "description": "Human reviews the completed brief", "output_field": "reviewed_brief"}, "fetch_questionnaire": {"action": "fetch_agent_questionnaire", "config": {"agent_type_field": "confirmed_type.recommended_builder"}, "next_step": "call_briefer", "description": "Fetch the briefing questionnaire for the target builder", "output_field": "questionnaire"}, "fetch_available_builders": {"action": "query_agent_definitions", "config": {"fields": ["type", "display_name", "description"], "filter": {"type_pattern": "%-builder"}}, "next_step": "spawn_classifier", "description": "Discover what builder agents are available", "output_field": "available_builders"}}, "start_step": "fetch_available_builders"}, "processing_mode": "orchestration", "timeout_seconds": 600}
